// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= address(c).balance + (2 ** 160));
        amount = bound(amount, 1, type(uint128).max);

        vm.deal(address(c), amount);
        uint256 before = address(c).balance;

        vm.prank(address(this));
        c.sendTo(receiver, amount);

        // Rule: after sendTo, c's balance has dropped by EXACTLY `amount` wei.
        assertTrue(before - address(c).balance == amount);
    }
}
